*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF41500.xml";
// grid resize 시작부
frame.SetEvent("onwinstat", OnWinStat);
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gOldWidthSize = frame.width;
scwin.gNewWidthSize = 0;
scwin.isCtrl = false;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.sleep = function(numberMillis) {
    var now = new Date();
    var exitTime = now.getTime() + numberMillis;
    while (true) {
        now = new Date();
        if (now.getTime() > exitTime) return;
    }

};
scwin.OnSized = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.gNewWidthSize = frame.width;
    scwin.GauceObjResize(frame.width, frame.height);
};
scwin.OnSizedMax = function(winID) {
    if (scwin.iTimer > 0) window.clearInterval(scwin.iTimer);
    scwin.iTimer = 0;
    scwin.maxval = 0;
    scwin.GauceObjResize($c.frame.path("/").width, frame.height);
};
scwin.OnWinStat = function(winID, statmsg) {
    if (statmsg == "activate" && winID.substring(0, 6) == "Child_") {
        $c.frame.path("/").WinActive(winID, statmsg);
    }
    if (statmsg == "maximize") {
        scwin.maxval = 1;
    } else if (statmsg == "size") {
        if (scwin.maxval == 0) {
            var strFnc = "OnSized('" + winID + "')";
            if (scwin.iTimer > 0) {
                window.clearInterval(scwin.iTimer);
                scwin.iTimer = 0;
            }
            scwin.iTimer = window.setInterval(strFnc, 300);
        } else if (scwin.maxval == 1) {
            scwin.OnSizedMax(winID);
            scwin.gOldWidthSize = $c.frame.path("/").width - 10;
        }
    }
};
scwin.GauceObjResize = function(a, b) {
    // 그리드메인
    var gw = (a - parseInt(grd_List.getStyle("width")) - 30);
    grd_List.ReDraw = "false";
    grd_List.setGridWidth(parseInt(grd_List.getStyle("width")) + gw);
    grd_List.ReDraw = "true";
    scwin.gOldWidthSize = frame.width;

    // 탭패널
    var pnl_main_grp = document.all("__GROUPBOX_BACKGROUND__" + "panel_Top");
    pnl_main_grp.style.setGridWidth(parseInt(pnl_main_grp.style.width.replace("px", "")) + gw); // 상단패널
    panel_Top.style.width = parseInt(panel_Top.style.width.replace("px", "")) + gw;
    // 조회버튼
    btn_Search.style.left = parseInt(btn_Search.style.left.replace("px", "")) + gw;
    // 저장버튼
    btn_Close.style.left = parseInt(btn_Close.style.left.replace("px", "")) + gw;
    btn_Excel.style.left = parseInt(btn_Excel.style.left.replace("px", "")) + gw;
};


// grid resize 종료부


scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fn_RefreshForm = function(interval) {
    setInterval("fn_list_sync();", interval);
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
};


/*직전영업일 가져옴*/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=GONGMOGA_JUGA_DONGHYANG_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.newlist.gongmoga.juga.donghyang.select" + "&{P}param01=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param02=" + $c.stf.getObjectValue(edt_EDate) + "&{P}param03=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param04=" + $c.stf.getObjectValue(edt_EDate) + "&{P}param05=" + $c.stf.getObjectValue(edt_SDate) + "&{P}param06=" + $c.stf.getObjectValue(edt_EDate);
    //var url =  "/ELWEaryEnd.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=listElwEaryEnd&inputMessageId=ELW_EARY_END_OUT"; 
    //	  url+= "&SDATE=" + getObjectValue(edt_SDate);
    //	  url+= "&EDATE=" + getObjectValue(edt_EDate);
    //	  url+= "&ISU_CD=" + getObjectValue(txb_ISU_CD);

    //alert(getObjectValue(edt_SDate)+"//"+getObjectValue(edt_EDate)+"//"+getObjectValue(txb_ISU_CD));
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_save = function() {
    var res = window.confirm("[ " + dts_List.getCellData(dts_List.getRowPosition(), 'ISU_KOR_ABBRV') + " ] 확인 저장 하겠습니까?");
    //alert(js_id+"//"+dts_List.NameString(dts_List.RowPosition,'ISU_CD')+"//"+dts_List.NameString(dts_List.RowPosition,'OCCR_DD')+"//"+dts_List.NameString(dts_List.RowPosition,'OCCR_TM'));
    if (res) {
        var url = "/ELWEaryEnd.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveELWEaryEnd";
        url += "&USR_ID=" + js_id;
        url += "&ISU_CD=" + dts_List.getCellData(dts_List.getRowPosition(), 'ISU_CD');
        url += "&OCCR_DD=" + dts_List.getCellData(dts_List.getRowPosition(), 'OCCR_DD');
        url += "&OCCR_TM=" + dts_List.getCellData(dts_List.getRowPosition(), 'OCCR_TM');
        dts_parameter.DataID = encodeURI(url);
        dts_parameter.reset();
    }
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_Excel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_List, "신규상장기업 공모가현황-주가동향", "", "8");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    //	fn_getDate();
    //	setObjectValue(edt_SDate, dts_getDate.NameString(1, "CALND_DD"));
    //	edt_SDate.text = vCurDate; 	// 일주일전 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    scwin.fn_list_sync();
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);

    //fn_RefreshForm(60000);

};
scwin.grd_List_OnCheckClick = function(col, colid, bCheck) {
    if (bCheck != 0) {
        scwin.fn_save();
    }
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    scwin.fn_list_sync();
    dts_List.reset();
};
scwin.dts_List_OnColumnChanged = function(row, colid) {
    if ((dts_List.getCellData(row, 'CHRG_CONFRM_YN') == 'T') &&
        (dts_List.OrgNameString(row, colid) != dts_List.getCellData(row, colid)) &&
        (colid < 9)) {
        $c.win.alert('변경불가');
        dts_List.undoRow(row);
    }

};
scwin.img_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
